-- Şebeke aktarımı (Netcad KML + hesap tabloları): Gülveren, Çelebiuşağı
-- Önce SQL-baca-vana-turleri ve SQL-hat-grup çalıştırılmış olmalı. Tek işlemde: bir hata olursa hiçbir şey yazılmaz.
-- Depo kaydı bu köylerde yoktu: çizimdeki başlangıç noktasında yeni depo açılır (konum yaklaşık).
-- Baca/vana konumu çizimdeki yazı (etiket) noktasından alındı: konum yaklaşık, sahada doğrulanacak.
begin;
-- ── Gülveren (Akpınar) ──
do $$
declare v_depo bigint; v_n int; v_b int; v_v int;
begin
  if exists (select 1 from tesis where tur in ('baca','vana') and koy = 'Gülveren' and ilce = 'Akpınar' and silindi is null) then raise exception 'Gülveren baca/vana kayıtları zaten var — aktarım yapılmadı'; end if;
  select coalesce(max((substring(kod from '[0-9]+$'))::int), 0) into v_n from tesis where kod like 'KS-DEP-%';
    values ('KS-DEP-' || lpad((v_n + 1)::text, 4, '0'), 'depo'::tesis_turu, 'aktif', 'Akpınar', 'Gülveren', 39.4505335, 33.8774797, true, 'BK-DEP-' || lpad((v_n + 1)::text, 4, '0'), 'Netcad çizimi (başlangıçtaki depo simgesi) — konum yaklaşık', '{"d":{},"photos":0}'::jsonb)
    returning id into v_depo;
  select coalesce(max((substring(kod from '[0-9]+$'))::int), 0) into v_b from tesis where kod like 'KS-BAC-%';
  select coalesce(max((substring(kod from '[0-9]+$'))::int), 0) into v_v from tesis where kod like 'KS-VAN-%';
end $$;

-- ── Çelebiuşağı (Akpınar) ──
do $$
declare v_depo bigint; v_n int; v_b int; v_v int;
begin
  if exists (select 1 from tesis where tur in ('baca','vana') and koy = 'Çelebiuşağı' and ilce = 'Akpınar' and silindi is null) then raise exception 'Çelebiuşağı baca/vana kayıtları zaten var — aktarım yapılmadı'; end if;
  select coalesce(max((substring(kod from '[0-9]+$'))::int), 0) into v_n from tesis where kod like 'KS-DEP-%';
    values ('KS-DEP-' || lpad((v_n + 1)::text, 4, '0'), 'depo'::tesis_turu, 'aktif', 'Akpınar', 'Çelebiuşağı', 39.5519742, 33.9037214, true, 'BK-DEP-' || lpad((v_n + 1)::text, 4, '0'), 'Netcad çizimi (başlangıçtaki depo simgesi) — konum yaklaşık', '{"d":{},"photos":0}'::jsonb)
    returning id into v_depo;
  select coalesce(max((substring(kod from '[0-9]+$'))::int), 0) into v_b from tesis where kod like 'KS-BAC-%';
  select coalesce(max((substring(kod from '[0-9]+$'))::int), 0) into v_v from tesis where kod like 'KS-VAN-%';
end $$;

commit;
